-- Least-privilege database roles.
-- Do NOT edit this file in place with real passwords -- it is tracked in
-- git. See the Technical Setup Runbook (Section 9.4) for the sed-based
-- method that substitutes real passwords into a temp copy instead.

-- logimind_app: used by the running FastAPI application.
-- Read-only on operational tables, plus INSERT on audit_log.
CREATE ROLE logimind_app LOGIN PASSWORD 'CHANGE_ME_APP_PASSWORD';
GRANT SELECT ON drivers, fuel_transactions, settlements, escrow_transactions,
    performance, shipments TO logimind_app;
GRANT SELECT, INSERT ON audit_log TO logimind_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO logimind_app;

-- logimind_ingest: reserved for future structured-data ingestion jobs.
-- (RAG document ingestion no longer runs through Postgres -- it writes to
-- ChromaDB via scripts/ingest_policies.py, a manually-run admin script
-- that never gets application-role credentials.)
CREATE ROLE logimind_ingest LOGIN PASSWORD 'CHANGE_ME_INGEST_PASSWORD';
GRANT INSERT ON audit_log TO logimind_ingest;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO logimind_ingest;

-- Note on LangGraph's checkpoint tables (checkpoints, checkpoint_blobs,
-- checkpoint_writes, checkpoint_migrations): these are created and owned
-- by whichever role calls checkpointer.setup() at app startup. Since the
-- running app connects as logimind_app, that role needs CREATE privilege
-- on the schema the first time it runs, OR you run setup() once as
-- logimind_admin and then grant logimind_app rights on those 4 tables:
--
-- GRANT SELECT, INSERT, UPDATE, DELETE ON checkpoints, checkpoint_blobs,
--     checkpoint_writes, checkpoint_migrations TO logimind_app;
-- GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO logimind_app;
